`timescale 1ns/1ps
module tb_pq_poly;
reg clk=0, rst_n=0; always #5 clk=~clk;
reg start=0; reg [4:0] op=0; reg [5:0] sa=0,sb=0,sc=0; reg g2sel=0; reg [31:0] bound=0;
wire busy, done, flag_or; wire [8:0] hint_cnt; wire [13:0] ra, wa; wire we; wire [31:0] wd, rq;
pq_pm pm(.clk(clk), .we(we), .wa(wa), .wd(wd), .ra(ra), .rq(rq));
pq_poly dut(clk,rst_n,start,op,sa,sb,sc,g2sel,bound,busy,done,flag_or,hint_cnt,ra,we,wa,wd,rq);
integer fails=0, n=0, i, c0, cyc=0; always @(posedge clk) cyc<=cyc+1; reg seen=0; always @(posedge clk) if (done) seen<=1;
task setp(input [5:0] s, input [8191:0] v); begin for (i=0;i<256;i=i+1) pm.mem[s*256+i] = v[32*i +: 32]; end endtask
task chk(input [5:0] s, input [8191:0] v, input [255:0] nm); begin for (i=0;i<256;i=i+1) if (pm.mem[s*256+i] !== v[32*i +: 32]) begin
   if (fails < 10) $display("FAIL slot %0d idx %0d got %h exp %h", s, i, pm.mem[s*256+i], v[32*i +: 32]); fails=fails+1; end end endtask
task run(input [4:0] o, input [5:0] a, input [5:0] b, input [5:0] c, input g, input [31:0] bd); begin
  seen=0; c0=cyc; @(negedge clk); op=o; sa=a; sb=b; sc=c; g2sel=g; bound=bd; start=1; @(negedge clk); start=0; wait(seen); repeat(3) @(negedge clk); end endtask
initial begin #30 rst_n=1; #30;
  setp(1, 8192');
  run(0,1,0,0,0,0); $display("ntt: %0d clk", cyc-c0);
  chk(1, 8192', "ntt");
  n=n+1;
  setp(2, 8192');
  run(0,2,0,0,0,0); $display("ntt_wide: %0d clk", cyc-c0);
  chk(2, 8192', "ntt_wide");
  n=n+1;
  setp(3, 8192');
  run(1,3,0,0,0,0); $display("intt: %0d clk", cyc-c0);
  chk(3, 8192', "intt");
  n=n+1;
  setp(5, 8192');
  setp(6, 8192');
  run(2,4,5,6,0,0); $display("pmul: %0d clk", cyc-c0);
  chk(4, 8192', "pmul");
  n=n+1;
  setp(7, 8192');
  setp(5, 8192');
  setp(6, 8192');
  run(3,7,5,6,0,0); $display("pmula: %0d clk", cyc-c0);
  chk(7, 8192', "pmula");
  n=n+1;
  setp(5, 8192');
  setp(6, 8192');
  run(4,8,5,6,0,0); $display("padd: %0d clk", cyc-c0);
  chk(8, 8192', "padd");
  n=n+1;
  setp(5, 8192');
  setp(6, 8192');
  run(5,9,5,6,0,0); $display("psub: %0d clk", cyc-c0);
  chk(9, 8192', "psub");
  n=n+1;
  setp(10, 8192');
  run(6,10,0,0,0,0); $display("pred: %0d clk", cyc-c0);
  chk(10, 8192', "pred");
  n=n+1;
  setp(11, 8192');
  run(7,11,0,0,0,0); $display("pcaddq: %0d clk", cyc-c0);
  chk(11, 8192', "pcaddq");
  n=n+1;
  setp(12, 8192');
  run(8,12,0,0,0,0); $display("pclr: %0d clk", cyc-c0);
  chk(12, 8192', "pclr");
  n=n+1;
  setp(5, 8192');
  run(9,13,5,0,0,0); $display("pcopy: %0d clk", cyc-c0);
  chk(13, 8192', "pcopy");
  n=n+1;
  setp(16, 8192');
  run(10,14,15,16,0,0); $display("p2r: %0d clk", cyc-c0);
  chk(14, 8192', "p2r");
  chk(15, 8192', "p2r");
  n=n+1;
  setp(19, 8192');
  run(11,17,18,19,0,0); $display("pdec88: %0d clk", cyc-c0);
  chk(17, 8192', "pdec88");
  chk(18, 8192', "pdec88");
  n=n+1;
  setp(21, 8192');
  setp(22, 8192');
  run(12,20,21,22,0,0); $display("mkhint88: %0d clk", cyc-c0);
  chk(20, 8192', "mkhint88");
  if (hint_cnt !== 9'd2) begin fails=fails+1; $display("FAIL mkhint88: hints %0d exp 2", hint_cnt); end
  n=n+1;
  setp(19, 8192');
  run(11,17,18,19,1,0); $display("pdec32: %0d clk", cyc-c0);
  chk(17, 8192', "pdec32");
  chk(18, 8192', "pdec32");
  n=n+1;
  setp(21, 8192');
  setp(22, 8192');
  run(12,20,21,22,1,0); $display("mkhint32: %0d clk", cyc-c0);
  chk(20, 8192', "mkhint32");
  if (hint_cnt !== 9'd2) begin fails=fails+1; $display("FAIL mkhint32: hints %0d exp 2", hint_cnt); end
  n=n+1;
  setp(23, 8192');
  run(13,23,0,0,0,200000); $display("chkn_ok: %0d clk", cyc-c0);
  if (flag_or !== 1'b0) begin fails=fails+1; $display("FAIL chkn_ok: flag %b exp 0", flag_or); end
  n=n+1;
  setp(24, 8192');
  run(13,24,0,0,0,200000); $display("chkn_neg: %0d clk", cyc-c0);
  if (flag_or !== 1'b1) begin fails=fails+1; $display("FAIL chkn_neg: flag %b exp 1", flag_or); end
  n=n+1;
  setp(25, 8192');
  run(13,25,0,0,0,200000); $display("chkn_edge: %0d clk", cyc-c0);
  if (flag_or !== 1'b1) begin fails=fails+1; $display("FAIL chkn_edge: flag %b exp 1", flag_or); end
  n=n+1;
  setp(26, 8192');
  run(13,26,0,0,0,2000000); $display("chkn_bigbound: %0d clk", cyc-c0);
  if (flag_or !== 1'b1) begin fails=fails+1; $display("FAIL chkn_bigbound: flag %b exp 1", flag_or); end
  n=n+1;
  if (fails==0) $display("ALL PASS (%0d ops)", n); else $display("FAILED (%0d mismatches)", fails);
  $finish;
end
initial begin #800000000 $display("TIMEOUT"); $finish; end
endmodule
